import { test, expect } from '@playwright/test';

test.describe('Search Input Focus', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://your-website-url.com'); // Replace with your actual URL
  });

  test('should focus on search input when "/" is pressed', async ({ page }) => {
    await page.keyboard.press('/');
    const searchInput = page.getByRole('textbox', { name: /search/i });
    await expect(searchInput).toBeFocused();
  });

  test('should remain focused on search input after typing', async ({ page }) => {
    await page.keyboard.press('/');
    const searchInput = page.getByRole('textbox', { name: /search/i });
    await expect(searchInput).toBeFocused();
    await searchInput.fill('test search');
    await expect(searchInput).toHaveValue('test search');
  });
});
